ty\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useMeditate(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/meikyo_shisui.lua"]={["Path"]="scripts/actions/abilities/meikyo_shisui.lua",["SHA256"]="90c164c05f10536d7f6e61276d7c939c91a8fa15fb26b2c87ffaab3bb388c691",["Text"]="-----------------------------------\n-- Ability: Meikyo Shisui\n-- Reduces cost of weapon skills.\n-- Obtained: Samurai Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.samurai.checkMeikyoShisui(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useMeikyoShisui(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mighty_strikes.lua"]={["Path"]="scripts/actions/abilities/mighty_strikes.lua",["SHA256"]="2a829ef868860d84a1a240aa61f250bdff4a8bfa043ee5abb80bb4aad1502529",["Text"]="-----------------------------------\n-- Ability: Mighty Strikes\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.warrior.checkMightyStrikes(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useMightyStrikes(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mijin_gakure.lua"]={["Path"]="scripts/actions/abilities/mijin_gakure.lua",["SHA256"]="5fe4932d8146fa62986f4da9ac28f4d8a5ff5dc38549cb8b287c90b7ea71bbe6",["Text"]="-----------------------------------\n-- Ability: Mijin Gakure\n-- Sacrifices user's life to deal damage to an enemy.\n-- Obtained: Ninja Level 1\n-- Recast Time: 1:00:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ninja.checkMijinGakure(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ninja.useMijinGakure(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mikage.lua"]={["Path"]="scripts/actions/abilities/mikage.lua",["SHA256"]="d100ff07c29a39d4e558ae4c629e7819fe7a26e069049f076132b5a51b5a1bbc",["Text"]="-----------------------------------\n-- Ability: Mikage\n-- Grants a bonus to number of main weapon attacks that varies with the number of remaining Utsusemi Shadow Images.\n-- Obtained: Ninja Level 96\n-- Recast Time: 1:00:00\n-- Duration: 45 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ninja.checkMikage(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ninja.useMikage(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/misers_roll.lua"]={["Path"]="scripts/actions/abilities/misers_roll.lua",["SHA256"]="d3019bfefde382100100dca0ca32a6949ef1ec8c99642cc9dc8c81d42c436742",["Text"]="-----------------------------------\n-- Ability: Miser's Roll\n-- Grants \"Save TP\" effect to party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 5\n-- Unlucky Number: 7\n-- Level: 92\n-- Phantom Roll +1 Value: 15\n--\n-- Die Roll    | Skillchain Bonus\n-- --------    -------\n-- 1           |+30\n-- 2           |+50\n-- 3           |+70\n-- 4           |+90\n-- 5           |+200\n-- 6           |+110\n-- 7           |+20\n-- 8           |+130\n-- 9           |+150\n-- 10          |+170\n-- 11          |+250\n-- Bust        |-0\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/modus_veritas.lua"]={["Path"]="scripts/actions/abilities/modus_veritas.lua",["SHA256"]="92ec4f04d8cbca051c7d763e302a6e915612b8d05321aa5846ff0a935733f825",["Text"]="-----------------------------------\n-- Ability: Modus Veritas\n-- Increases damage done by helix spells while lowering spell duration by 50%.\n-- Obtained: Scholar Level 65\n-- Recast Time: 3:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local helix = target:getStatusEffect(xi.effect.HELIX)\n    if not helix then\n        ability:setMsg(xi.msg.basic.JA_NO_EFFECT_2) -- No effect\n        return 0\n    end\n\n    local mvPower = helix:getSubPower()\n    local params  = { skillType = xi.skill.ELEMENTAL_MAGIC }\n    local resist  = xi.combat.magicHitRate.calculateResistRate(player, target, params)\n\n    -- Doesn't work against NMs apparently\n    if mvPower > 0 or resist < 0.25 or target:isNM() then -- Don't let Modus Veritas stack to prevent abuse\n        ability:setMsg(xi.msg.basic.JA_MISS) --Miss\n        return 0\n    end\n\n    -- Double power and halve remaining time\n    local durationMultiplier = 0.5 + 0.05 * player:getMerit(xi.merit.MODUS_VERITAS_DURATION)\n    local helixPower         = 2 * helix:getPower() + 3 * player:getJobPointLevel(xi.jp.MODUS_VERITAS_EFFECT)\n    local duration           = math.floor(helix:getDuration() / 1000)      -- from milliseconds\n    local remaining          = math.floor(helix:getTimeRemaining() / 1000) -- from milliseconds\n\n    duration = duration - remaining + math.floor(remaining * durationMultiplier)\n    helix:setSubPower(mvPower + 1)\n    helix:setPower(helixPower)\n    helix:setDuration(duration * 1000) -- back to milliseconds\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/monks_roll.lua"]={["Path"]="scripts/actions/abilities/monks_roll.lua",["SHA256"]="138b2b00d447f7063c20963e2f4571222501bee39194ef096242ef4ac24ed8d0",["Text"]="-----------------------------------\n-- Ability: Monk's Roll\n-- Enhances \"Subtle Blow\" effect for party members within area of effect\n-- Optimal Job: Monk\n-- Lucky Number: 3\n-- Unlucky Number: 7\n-- Level: 31\n-- Phantom Roll +1 Value: 4\n--\n-- Die Roll    |No MNK  |With MNK\n-- --------    -------- -----------\n-- 1           |+8      |+18\n-- 2           |+10     |+20\n-- 3           |+32     |+42\n-- 4           |+12     |+22\n-- 5           |+14     |+24\n-- 6           |+16     |+26\n-- 7           |+4      |+14\n-- 8           |+20     |+30\n-- 9           |+22     |+32\n-- 10          |+24     |+34\n-- 11          |+40     |+50\n-- Bust        |-11     |-11\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/mug.lua"]={["Path"]="scripts/actions/abilities/mug.lua",["SHA256"]="59bacc18a4d1acdee70d95aec857de4cbb4fc460424ae57221d2b08e3ab0e90c",["Text"]="-----------------------------------\n-- Ability: Mug\n-- Steal gil from enemy.\n-- Obtained: Thief Level 35\n-- Recast Time: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.thief.useMug(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/naturalists_roll.lua"]={["Path"]="scripts/actions/abilities/naturalists_roll.lua",["SHA256"]="afa3018c9836eceaf2ffea409662e262def7ac3fd0b4c8cfeef9765697f35971",["Text"]="-----------------------------------\n-- Ability: Naturalists's Roll\n-- Increases the duration of enhancing magic effects received for party members within area of effect.\n-- Optimal Job: Geomancer\n-- Lucky Number: 3\n-- Unlucky Number: 7\n-- Level: 67\n-- Phantom Roll +1 Value: 1\n--\n-- Die Roll    | Duration %\n-- --------    -------\n-- 1           |+6\n-- 2           |+7\n-- 3           |+15\n-- 4           |+8\n-- 5           |+9\n-- 6           |+10\n-- 7           |+5\n-- 8           |+11\n-- 9           |+12\n-- 10          |+13\n-- 11          |+20\n-- Bust        |-5\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/nether_void.lua"]={["Path"]="scripts/actions/abilities/nether_void.lua",["SHA256"]="08c2ae0360cb455c37b4844de51e6d10542f8d6a6b53944a2e3acc283f05da98",["Text"]="-----------------------------------\n-- Ability: Nether Void\n-- Description: Increases the absorption of your next dark magic spell.\n-- Obtained: Dark Knight Level 78\n-- Recas