nAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/no_foot_rise.lua"]={["Path"]="scripts/actions/abilities/no_foot_rise.lua",["SHA256"]="c1f5f572ef65a7c3cd1b340987321c933159d958e232524269302754a9f6ec2b",["Text"]="-----------------------------------\n-- Ability: No Foot Rise\n-- Instantly grants additional Finishing Moves.\n-- Obtained: Dancer Level 75 Merit Group 2\n-- Recast Time: 3 minutes\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkNoFootRiseAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dancer.useNoFootRiseAbility(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/one_for_all.lua"]={["Path"]="scripts/actions/abilities/one_for_all.lua",["SHA256"]="7ad13048aef8fca50ca7e33defa7e042297f59f3ff15dfdb1d60df5a4bfc7f09",["Text"]="-----------------------------------\n-- Ability: One for All\n-- Grants a Magic Shield effect for party members within area of effect.\n-- Obtained: Rune Fencer Level 95\n-- Recast Time: 0:30\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useOneForAll(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/overdrive.lua"]={["Path"]="scripts/actions/abilities/overdrive.lua",["SHA256"]="5534ede30a4db5a58c668b7dd40bf4e59e855f64a5abea8643af7e1098bc7dc9",["Text"]="-----------------------------------\n-- Ability: Overdrive\n-- Augments the fighting ability of your automaton to its maximum level.\n-- Obtained: Puppetmaster Level 1\n-- Recast Time: 1:00:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckOverdrive(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.puppetmaster.onAbilityUseOverdrive(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/overkill.lua"]={["Path"]="scripts/actions/abilities/overkill.lua",["SHA256"]="e34d73c431953a012c66669c5e92bd5d872b064ce8d27fb6d61b35858c160c70",["Text"]="-----------------------------------\n-- Ability: Overkill\n-- Description: Increases ranged attack speed and the chance of activating Double/Triple Shot.\n-- Obtained: RNG Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkOverkill(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useOverkill(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/palisade.lua"]={["Path"]="scripts/actions/abilities/palisade.lua",["SHA256"]="6e9e68780b4b8b262a310ab291a913a609b87675de4091e1553b3a679028b197",["Text"]="-----------------------------------\n-- Ability: Palisade\n-- Description: Increases chance of blocking with shield, and eliminates enmity loss.\n-- Obtained: PLD Level 95\n-- Recast Time: 00:05:00\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.paladin.usePalisade(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/parsimony.lua"]={["Path"]="scripts/actions/abilities/parsimony.lua",["SHA256"]="05427b2e7a40558e93f1e85766ec132d4b9726e68cb5fc4006f477b639053165",["Text"]="-----------------------------------\n-- Ability: Parsimony\n-- Reduces the MP cost of your next black magic spell by 50%.\n-- Obtained: Scholar Level 10\n-- Recast Time: Stratagem Charge\n-- Duration: 1 black magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.PARSIMONY) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.PARSIMONY, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.PARSIMONY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/penury.lua"]={["Path"]="scripts/actions/abilities/penury.lua",["SHA256"]="cfa67a76cf65ad065f306d73ec8dd1433d8213cd0c7b18ff510da3ad842b5c40",["Text"]="-----------------------------------\n-- Ability: Penury\n-- Reduces the MP cost of your next white magic spell by 50%.\n-- Obtained: Scholar Level 10\n-- Recast Time: Stratagem Charge\n-- Duration: 1 white magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.PENURY) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.PENURY, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.PENURY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/perfect_counter.lua"]={["Path"]="scripts/actions/abilities/perfect_counter.lua",["SHA256"]="fed9371a1479c1eb589005f3f15f6770c2d6c011177a8e5812a586d390d3ec3c",["Text"]="-----------------------------------\n-- Ability: Perfect Counter\n-- Description: Allows you to counter the next attack directed at you.\n-- Obtained: MNK Level 79\n-- Recast Time: 00:01:00\n-- Duration: 0:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.usePerfectCounter(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/perfect_dodge.lua"]={["Path"]="scripts/actions/abilities/perfect_dodge.lua",["SHA256"]="7c78f462c82479b883094a504020befa066450edebda2557452c0c28c84a0a3f",["Text"]="-----------------------------------\n-- Ability: Perfect Dodge\n-- Allows you to dodge all melee attacks.\n-- Obtained: Thief Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.thief.checkPerfectDodge(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.usePerfectDodge(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/perpetuance.lua"]={["Path"]="scripts/actions/abilities/perpetuance.lua",["SHA256"]="a03bbc0fbc3508e3d0e760f68fcc27d6ccc80207aa855d2a0f6309b12f88e74c",["Text"]="-----------------------------------\n-- Ability: Perpetuance\n-- Increases the enhancement effect duration of your next white magic spell.\n-- Obtained: Scholar Level 87\n-- Recast Time: Stratagem Charge\n-- Duration: 00:01:00 or first white Enhancing Magic cast, whichever first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.PERPETUANCE) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.PERPETUANCE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.PERPETUANCE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/acid_mist.lua"]={["Path"]="scripts/actions/abilities/pets/acid_mist.lua",["SHA256"]="650e14a3b83378a7f6c16c22856a4d614f18ef95e6fb1e098bd54a40e7a14a87",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'acid_mist_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/aerial_armor.lua"]={["Path"]="scripts/actions/abilities/pets/aerial_armor.lua",["SHA256"]="d626782df8e1163acfd1727301f55c931c1e5920dc143dd9a7b15c743ee84e49",["Text"]="-----------------------------------\n-- Aerial Armor\n-- Family: Avatar (Garuda)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    target:delStatusEffect(xi.effect.BLINK) -- TODO: Capture overwrite tiers\n\n    if target:addStatusEffect(xi.effect.BLINK, { power = 3, duration = 900, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.BLINK\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/aerial_blast.lua"]={["Path"]="scripts/actions/abilities/pets/aerial_blast.lua",["SHA256"]="fbf882cb559ed19756919ce7b79a6091a77fc3c69a4b38eecc25a1ab7b88c0b7",["Text"]="-----------------------------------\n-- Aerial Blast\n-- Family: Garuda\n-- Note: Garuda's Astral Flow\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.WIPE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/aero_ii.lua"]={["Path"]="scripts/actions/abilities/pets/aero_ii.lua",["SHA256"]="e5cd27ac0b8410a64a89c9719fcd77c1df6ec55ce3b1799439cc9b3deb7068ea",["Text"]="-----------------------------------\n-- Aero II\n-- Family: Garuda (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 1.500, 2.750, 3.125 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/aero_iv.lua"]={["Path"]="scripts/actions/abilities/pets/aero_iv.lua",["SHA256"]="6cdd238e02c18d6b5cb4a151020e5ddb47e3b311bd948f55dc3c1ae66244afba",["Text"]="-----------------------------------\n-- Aero IV\n-- Family: Garuda (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 3.6250, 5.3125, 6.1250 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/altana_s_favor.lua"]={["Path"]="scripts/actions/abilities/pets/altana_s_favor.lua",["SHA256"]="1f20fd407ed1f79455668d23811828acbeda1346084931c3c2fb4ab181da1be3",["Text"]="-----------------------------------\n-- Altana's Favor\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    if not target:isPC() then\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return 0\n    end\n\n    summoner:setMP(0)\n\n    if target:isDead() then\n        target:sendRaise(4) -- arise\n    elseif target:addStatusEffect(xi.effect.RERAISE, { power = 3, origin = pet }) then -- Infinite duration http://wiki.ffo.jp/html/30976.html\n        petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        return xi.effect.RERAISE\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return 0\n    end\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/aqua_breath.lua"]={["Path"]="scripts/actions/abilities/pets/aqua_breath.lua",["SHA256"]="02933cf3756318ab5c9c384e4b977ccd7c3b8d7cb90f794418a8c4fa065d77b8",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'aqua_breath_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"}};
